package com.gbconnected.kpivalidation.functions;
import com.gbconnected.kpivalidation.application.*;import com.gbconnected.kpivalidation.application.approval.scope.*;import com.google.gson.*;import com.microsoft.azure.functions.*;import com.microsoft.azure.functions.annotation.*;import java.util.*;
public class KpiApprovalScopeFunctions {
 private static final String CORRELATION="X-Correlation-Id";
 @FunctionName("kpi-approval-scope-policy") public HttpResponseMessage policy(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/kpi-approval/scope/policy",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,ExecutionContext ctx){return json(req,HttpStatus.OK,FunctionRuntime.RUNTIME.kpiApprovalScopeAdministration().policy(),correlation(req));}
 @FunctionName("kpi-approval-scope-list") public HttpResponseMessage list(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/kpi-approval/scope/admin/assignments",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,ExecutionContext ctx){String c=correlation(req);try{long plant=Long.parseLong(req.getQueryParameters().getOrDefault("plantId","0"));return json(req,HttpStatus.OK,FunctionRuntime.RUNTIME.kpiApprovalScopeAdministration().list(FunctionActorContextResolver.resolve(req),plant),c);}catch(Exception e){return reject(req,e,c);}}
 @FunctionName("kpi-approval-scope-assign") public HttpResponseMessage assign(@HttpTrigger(name="req",methods={HttpMethod.POST},route="v1/kpi-approval/scope/admin/assignments",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,ExecutionContext ctx){String c=correlation(req);try{JsonObject b=body(req);var out=FunctionRuntime.RUNTIME.kpiApprovalScopeAdministration().assign(FunctionActorContextResolver.resolve(req),new AssignKpiApproverPlantCommand(b.get("targetUserId").getAsLong(),b.get("plantId").getAsLong(),text(b,"reason")),c);ctx.getLogger().info("event=kpi_approval_scope_assigned targetUserId="+out.userId()+" plantId="+out.plantId()+" correlationId="+c);return json(req,HttpStatus.OK,out,c);}catch(Exception e){return reject(req,e,c);}}
 @FunctionName("kpi-approval-scope-revoke") public HttpResponseMessage revoke(@HttpTrigger(name="req",methods={HttpMethod.DELETE},route="v1/kpi-approval/scope/admin/assignments",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,ExecutionContext ctx){String c=correlation(req);try{JsonObject b=body(req);var out=FunctionRuntime.RUNTIME.kpiApprovalScopeAdministration().revoke(FunctionActorContextResolver.resolve(req),new RevokeKpiApproverPlantCommand(b.get("targetUserId").getAsLong(),b.get("plantId").getAsLong(),text(b,"reason")),c);ctx.getLogger().info("event=kpi_approval_scope_revoked targetUserId="+out.userId()+" plantId="+out.plantId()+" correlationId="+c);return json(req,HttpStatus.OK,out,c);}catch(Exception e){return reject(req,e,c);}}
 private static JsonObject body(HttpRequestMessage<Optional<String>> r){return JsonParser.parseString(r.getBody().orElseThrow(()->new IllegalArgumentException("JSON body is required"))).getAsJsonObject();}
 private static String text(JsonObject b,String n){return b.has(n)&&!b.get(n).isJsonNull()?b.get(n).getAsString():null;}
 private static HttpResponseMessage reject(HttpRequestMessage<?>r,Exception e,String c){HttpStatus s=e instanceof SecurityException?HttpStatus.UNAUTHORIZED:e instanceof AuthorizationException?HttpStatus.FORBIDDEN:e instanceof KpiApprovalScopeConflictException?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;return r.createResponseBuilder(s).header(CORRELATION,c).header("Content-Type","application/json").body(JsonCodec.GSON.toJson(Map.of("error",e.getMessage()==null?"Request rejected":e.getMessage()))).build();}
 private static HttpResponseMessage json(HttpRequestMessage<?>r,HttpStatus s,Object b,String c){return r.createResponseBuilder(s).header(CORRELATION,c).header("Content-Type","application/json").body(JsonCodec.GSON.toJson(b)).build();}
 private static String correlation(HttpRequestMessage<?>r){return r.getHeaders().entrySet().stream().filter(e->e.getKey().equalsIgnoreCase(CORRELATION)).map(Map.Entry::getValue).findFirst().filter(v->!v.isBlank()).orElse(UUID.randomUUID().toString());}
}
